; Start values of the fighters
; $811d-$8169

; Sets both fighters to the start of a bout: start positions, move $00, facing, energy and score 0. Sets the walk-in flag.
init_fighters
        ldx #$01
init_fighters_loop
        lda #$00
        sta fighter_move_step,x
        sta fighter_move_lock,x
        lda fighter_start_column,x      ; Start position: $00 for fighter 0, $1f for fighter 1.
        sta fighter_x,x
        lda #$80
        sta fighter_move,x
        txa
        sta fighter_facing,x            ; Fighter 0 faces right, fighter 1 faces left.
        jsr reset_fighter
        jsr clear_fighter_score
        dex
        bpl init_fighters_loop
        stx walk_in_active              ; X = $ff: the fighters walk in.
        rts
; Resets fighter X for a bout. A is the corner animation (stored with bit 7 set). Energy 12, idle timer $ff.
reset_fighter
        ora #$80
        sta corner_anim,x
        lda #$04
        sta corner_anim_pos,x
        lda #$0c
        sta fighter_energy,x
        lda #$ff
        sta fighter_idle_timer,x
        rts
; Sets the 5 score digits of fighter X to 0. The score is the text $87 (fighter 0) or $88 (fighter 1).
clear_fighter_score
        txa
        clc
        adc #$87
        asl
        tay
        lda text_ptrs,y
        sta text_ptr
        lda text_ptrs+1,y
        sta text_ptr+1
        ldy #$03                        ; The digits are at offset 3-7 of the text.
clear_fighter_score_loop
        lda #$30
        sta (text_ptr),y
        iny
        cpy #$08
        bcc clear_fighter_score_loop
        rts
